Worked example:

```javascript
function renameNote(notes,id,title) {
  return notes.map(note=>note.id === id ? {...note,title} : note);
}
console.log(renameNote([{"id":1,"title":"Moon"},{"id":2,"title":"Sea"}], 2, "Ocean"));
```
The returned value is [{"id":1,"title":"Moon"},{"id":2,"title":"Ocean"}].

after:
```javascript
function renameNote(notes,id,title) {
  return notes.map(note=>note.id === id ? {...note,title} : note);
}
console.log(renameNote([{"id":1,"title":"Moon"},{"id":2,"title":"Sea"}], 2, "Ocean"));
```
The result keeps Moon and changes Sea to Ocean. The input array still contains its original titles.
